const subcontractHeldQty = `-- name: SubcontractHeldQty :many
SELECT x.item_id, SUM(x.qty * CASE WHEN t.kind = 'issue' THEN 1 ELSE -1 END)::numeric AS qty
FROM subcontract_txn_lines x JOIN subcontract_txns t ON t.id = x.txn_id
WHERE t.order_id = $1 AND t.status = 'posted'
GROUP BY x.item_id
`

type SubcontractHeldQtyRow struct {
	ItemID int64
	Qty    decimal.Decimal
}

// 委外單目前還在加工廠的材料數量(發料 − 退料 − 收回耗用),依料品
func (q *Queries) SubcontractHeldQty(ctx context.Context, orderID int64) ([]SubcontractHeldQtyRow, error) {
	rows, err := q.db.Query(ctx, subcontractHeldQty, orderID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SubcontractHeldQtyRow{}
	for rows.Next() {
		var i SubcontractHeldQtyRow
		if err := rows.Scan(&i.ItemID, &i.Qty); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const subcontractReceivedQty = `-- name: SubcontractReceivedQty :one
SELECT COALESCE(SUM(qty), 0)::numeric FROM subcontract_txns WHERE order_id = $1 AND kind = 'receive' AND status = 'posted'
`

func (q *Queries) SubcontractReceivedQty(ctx context.Context, orderID int64) (decimal.Decimal, error) {
	row := q.db.QueryRow(ctx, subcontractReceivedQty, orderID)
	var column_1 decimal.Decimal
	err := row.Scan(&column_1)
	return column_1, err
}

